import{_ as l,a as i,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const _=JSON.parse('{"title":"MySQL 5.6、5.7 与 8.0 版本差异","description":"按 MySQL 5.6、5.7、8.0 对照存储和查询功能变化。","frontmatter":{"title":"MySQL 5.6、5.7 与 8.0 版本差异","description":"按 MySQL 5.6、5.7、8.0 对照存储和查询功能变化。","sources":[{"repository":"jekyall_blog","file":"_posts/DataStorage/mysql/2019-03-01-mysql-version-info.md","date":"Sat Apr 18 2020 12:21:48 GMT+0800 (中国标准时间)"}],"showdocs":{"topics":[{"id":"mysql","title":"MySQL","link":"/topics/mysql/"}],"kind":"知识专题","scope":"historical","audience":"general","group":"数据库与存储","summary":"按 MySQL 5.6、5.7、8.0 对照存储和查询功能变化。","status":"active","related":[{"title":"01 · 连接数据库与准备练习数据","link":"/middleware/mysql/base/mysql-crash-course-2/01-start","kind":"知识专题","scope":"general","audience":"general"},{"title":"02 · 检索、排序与条件过滤","link":"/middleware/mysql/base/mysql-crash-course-2/02-filtering","kind":"知识专题","scope":"general","audience":"general"},{"title":"03 · 计算、汇总与多表查询","link":"/middleware/mysql/base/mysql-crash-course-2/03-querying","kind":"知识专题","scope":"general","audience":"general"},{"title":"04 · 数据写入、表结构与视图","link":"/middleware/mysql/base/mysql-crash-course-2/04-tables","kind":"知识专题","scope":"general","audience":"general"},{"title":"05 · 存储程序与事务边界","link":"/middleware/mysql/base/mysql-crash-course-2/05-programming","kind":"知识专题","scope":"general","audience":"general"}],"prev":false,"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":false},"headers":[],"relativePath":"middleware/mysql/plus/subjects/mysql-version-info.md","filePath":"middleware/mysql/plus/subjects/mysql-version-info.md"}'),s={name:"middleware/mysql/plus/subjects/mysql-version-info.md"};function r(o,e,t,d,m,c){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="mysql-5-6、5-7-与-8-0-版本差异" tabindex="-1">MySQL 5.6、5.7 与 8.0 版本差异 <a class="header-anchor" href="#mysql-5-6、5-7-与-8-0-版本差异" aria-label="Permalink to &quot;MySQL 5.6、5.7 与 8.0 版本差异&quot;">​</a></h1><blockquote><p><strong>M4版本边界（2026-10-17）：</strong> 这是5.6、5.7、8.0的历史功能对照，不是当前版本选型建议。旧文性能倍数缺少本地负载证据；Online DDL仍受具体操作、ALGORITHM与LOCK约束，不能保证任意ALTER均不阻塞。现行8.4.7实验版本和边界见<a href="/middleware/mysql/base/basic/start#environment">起步</a>。</p></blockquote><p><span id="mysql-version-diff"></span></p><h2 id="_5-6" tabindex="-1">5.6 <a class="header-anchor" href="#_5-6" aria-label="Permalink to &quot;5.6&quot;">​</a></h2><ul><li>InnoDb 开始支持全文索引</li><li>InnoDb 支持设置页面大小</li><li>通过 innodb_page_size 指定，默认是 16KB，对于工作负载和存储设备（尤其是具有小块大小的 SSD 设备）的某些组合，较小的页面大小可以帮助避免冗余或低效的 I / O</li><li>InnoDB redolog 总大小的限制从之前的 4G 扩展至 512G</li><li>InnoDB 现在可以限制大量表打开的时候内存占用过多的问题(比如这里提到的)(第三方已有补丁)</li><li>InnoDB 性能加强。如分拆 kernel mutex;flush 操作从主线程分离;多个 perge 线程;大内存优化等</li><li>InnoDB 死锁信息可以记录到 error 日志，方便分析</li><li>优化器性能提升，引入了 ICP，MRR，BKA 等特性，针对子查询进行了优化</li><li>Undo Log 可保存在独立表空间中，因其是随机 IO，更适合放到 SSD 中。但仍然不支持空间的自动回收</li><li>支持部分 Online DDL 操作；是否允许并发 DML 取决于具体 ALTER、ALGORITHM 与 LOCK，准备/提交阶段仍可能等待元数据锁。不能理解为任意 ALTER 都不阻塞。参见<a href="https://dev.mysql.com/doc/refman/8.4/en/innodb-online-ddl-limitations.html" target="_blank" rel="noopener noreferrer">官方限制</a>。</li><li>MySQL 现在支持延迟复制，以便从属服务器故意落后于主服务器至少指定的时间量。默认延迟为 0 秒</li><li>之前，TIMESTAMP 每个表最多可以自动将一列初始化或更新为当前日期和时间，目前已没有该限制</li></ul><h2 id="_5-7" tabindex="-1">5.7 <a class="header-anchor" href="#_5-7" aria-label="Permalink to &quot;5.7&quot;">​</a></h2><ul><li>支持组复制和 InnoDB Cluster</li><li>支持多源复制</li><li>支持在线修改 Buffer pool 的大小</li><li>支持 UNDO 表空间的自动回收</li><li>查询优化器的增强与重构，提升性能</li><li>可查看当前 session 正在执行的 SQL 的执行计划(EXPLAIN FOR CONNECTION)</li><li>优化了 Performance Schema，其内存使用减少</li><li>原生支持 JSON 类型，并引入了众多 JSON 函数</li><li>可设置 SELECT 操作的超时时长（max_execution_time）</li><li>引入了 innodb_deadlock_detect 选项，在高并发场景下，可使用该选项来关闭死锁检测</li><li>GIS 的增强，包括使用 Boost.Geometry 替代之前的 GIS 算法，InnoDB 开始支持空间索引</li></ul><h2 id="_8-0" tabindex="-1">8.0 <a class="header-anchor" href="#_8-0" aria-label="Permalink to &quot;8.0&quot;">​</a></h2><ul><li>性能宣传的历史记录：原笔记称“比 5.7 快 2 倍”，未提供测试负载、硬件与来源，不能据此预测项目性能。</li><li>PERFORMANCE_SCHEMA 查询性能提升，其已内置多个索引</li><li>支持不可见索引(Invisible index)</li><li>支持降序索引</li><li>引入了 innodb<em>dedicated_server 选项，可基于服务器的内存来动态设置 innodb_buffer_pool_size，innodb_log_file</em>- size 和 innodb_flush_method</li><li>支持秒加字段(Instant add column)功能</li><li>JSON 字段的部分更新（JSON Partial Updates）</li><li>支持自增主键的持久化</li><li>默认字符集由 latin1 修改为 utf8mb4</li><li>默认开启 UNDO 表空间，且支持在线调整数量（innodb_undo_tablespaces）。在 MySQL - 5.7 中，默认不开启，若要开启，只能初始化时设置</li><li>Redo Log 的优化，包括允许多个用户线程并发写入 log buffer，可动态修改 innodb_log_buffer_size 的大小</li><li>默认的内存临时表由 MEMORY 引擎更改为 TempTable 引擎，相比于前者，后者支持以变长方式存储 VARCHAR，VARBINARY 等- 变长字段。从 MySQL 8.0.13 开始，TempTable 引擎支持 BLOB 字段</li><li>SELECT ... FOR SHARE 和 SELECT ... FOR UPDATE 语句中引入 NOWAIT 和 SKIP LOCKED 选项，解决电商场景热点行问题</li><li>正则表达式的增强，新增了 4 个相关函数，REGEXP_INSTR()，REGEXP_LIKE()，REGEXP_REPLACE()，REGEXP_SUBSTR()</li><li>查询优化器在制定执行计划时，会考虑数据是否在 Buffer Pool 中。而在此之前，是假设数据都在磁盘中</li><li>GROUP BY 语句不再隐式排序</li><li>增加了对于客户端报错信息的统计（performance_schema.events_errors_summary_xxx）</li><li>BLOB, TEXT, GEOMETRY 和 JSON 字段允许设置默认值</li></ul>',9)])])}const f=l(s,[["render",r]]);export{_ as __pageData,f as default};
